package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AResultEvidenceRepository implements A2AResultEvidenceRepository { private final A2AResultEvidenceDao dao; private final A2APersistenceConverter c; public MybatisA2AResultEvidenceRepository(A2AResultEvidenceDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2AResultEvidence save(A2AResultEvidence v){dao.insert(c.toPo(v));return v;} public List<A2AResultEvidence> findByAttempt(String t,String id,int n){return dao.findByAttempt(t,id,cap(n)).stream().map(c::toDomain).toList();} public String mode(){return "MYBATIS";} private int cap(int n){return Math.max(1,Math.min(n,1000));} }
